SET NAMES utf8mb4 COLLATE utf8mb4_unicode_ci;

-- Phase 6 SEO regression (docs/seo/regression.md) — keep the keywords the old pages ranked for.
-- Each statement only applies while the text is still the original (a CMS edit is never overwritten).

-- / (th): the old home title targeted "ระบบขายตรง" — it was only in the meta description, not on the page
-- why.lead: ผู้พัฒนาระบบ MLM ที่ธุรกิจเครือข่ายไว้วางใจให้ดูแลระบบ → ผู้พัฒนาระบบขายตรงและระบบ MLM ที่ธุรกิจเครือข่ายไว้วางใจให้ดูแลระบบ
UPDATE pages SET blocks = REPLACE(blocks, CONVERT(X'' USING utf8mb4), CONVERT(X'' USING utf8mb4)), updated_at = NOW()
WHERE path = CONVERT(X'2F' USING utf8mb4) COLLATE utf8mb4_bin AND locale = 'th' AND deleted_at IS NULL
  AND LOCATE(CONVERT(X'' USING utf8mb4), blocks) > 0;

-- /นโยบายความเป็นส่วนตัวข/: H1 back to the old wording (old H1: นโยบายความเป็นส่วนตัวของข้อมูล (Privacy Policy))
UPDATE pages SET title = CONVERT(X'E0B899E0B982E0B8A2E0B89AE0B8B2E0B8A2E0B884E0B8A7E0B8B2E0B8A1E0B980E0B89BE0B987E0B899E0B8AAE0B988E0B8A7E0B899E0B895E0B8B1E0B8A7E0B882E0B8ADE0B887E0B882E0B989E0B8ADE0B8A1E0B8B9E0B8A520285072697661637920506F6C69637929' USING utf8mb4), updated_at = NOW()
WHERE path = CONVERT(X'2FE0B899E0B982E0B8A2E0B89AE0B8B2E0B8A2E0B884E0B8A7E0B8B2E0B8A1E0B980E0B89BE0B987E0B899E0B8AAE0B988E0B8A7E0B899E0B895E0B8B1E0B8A7E0B8822F' USING utf8mb4) COLLATE utf8mb4_bin AND locale = 'th' AND deleted_at IS NULL AND title = CONVERT(X'E0B899E0B982E0B8A2E0B89AE0B8B2E0B8A2E0B884E0B8A7E0B8B2E0B8A1E0B980E0B89BE0B987E0B899E0B8AAE0B988E0B8A7E0B899E0B895E0B8B1E0B8A720285072697661637920506F6C69637929' USING utf8mb4) COLLATE utf8mb4_unicode_ci;
